  ('paris-data-engineering-meetup-18', 'Paris Data Engineering Meetup #18', 'Deux retours d''expérience sur des pipelines lakehouse en production, suivis d''un temps de networking.', 'Au programme : migration d''un entrepôt historique vers une architecture médaillon, puis industrialisation de la qualité de données avec des tests automatisés. Les talks durent 25 minutes chacun, avec questions.', '2026-10-08T19:00:00+02:00', '2026-10-08T21:30:00+02:00', 'scheduled', 'in_person', 'Paris', 'Paris 13e', 'data', array['Data Engineering', 'Lakehouse', 'Qualité de données'], array['Databricks', 'dbt', 'Python'], array['Data engineers', 'Data analysts'], 'Intermédiaire', true, 0, 0, 'Paris Data Engineers', 'https://example.com/paris-data-engineering-meetup-18'),
  ('atelier-agents-llm-production', 'Atelier pratique : mettre des agents LLM en production', 'Une journée hands-on pour concevoir, évaluer et monitorer un agent LLM connecté à des outils métier.', 'Matinée consacrée à l''architecture d''un agent et à l''appel d''outils, après-midi dédié à l''évaluation et à l''observabilité. Ordinateur portable requis, environnement fourni.', '2026-10-14T09:30:00+02:00', '2026-10-14T17:30:00+02:00', 'scheduled', 'in_person', 'Paris', 'Paris 2e', 'ai', array['GenAI', 'Agents', 'LLMOps'], array['Python', 'LangGraph', 'OpenTelemetry'], array['Développeurs', 'Data scientists'], 'Avancé', false, 150, 150, 'Collectif IA Appliquée', 'https://example.com/atelier-agents-llm'),
  ('lyon-cloud-native-night-octobre', 'Lyon Cloud Native Night', 'Soirée communautaire autour de Kubernetes, du platform engineering et de l''observabilité.', 'Trois talks courts, une démo live d''un portail développeur interne, puis apéritif offert par l''hôte.', '2026-10-15T18:30:00+02:00', '2026-10-15T21:00:00+02:00', 'scheduled', 'in_person', 'Lyon', 'Lyon Part-Dieu', 'cloud', array['Kubernetes', 'Platform engineering'], array['Kubernetes', 'Backstage', 'Grafana'], array['DevOps', 'SRE', 'Développeurs'], 'Intermédiaire', true, 0, 0, 'Cloud Native Lyon', 'https://example.com/lyon-cloud-native-night'),
  ('afterwork-cyber-lille', 'Afterwork cybersécurité Lille', 'Retour d''expérience sur la gestion d''un incident ransomware, puis échanges entre professionnels de la sécurité.', null, '2026-10-21T18:30:00+02:00', '2026-10-21T21:00:00+02:00', 'scheduled', 'in_person', 'Lille', 'Euratechnologies', 'cyber', array['SOC', 'Réponse à incident'], '{}'::text[], array['RSSI', 'Analystes SOC'], 'Tous niveaux', true, 0, 0, 'Cyber Hauts-de-France', 'https://example.com/afterwork-cyber-lille'),
  ('hackathon-ia-mobilite-toulouse', 'Hackathon IA et mobilité', '48 heures pour prototyper des services de mobilité à partir de données ouvertes de transport.', 'Équipes de 3 à 5 personnes, jeux de données GTFS et trafic fournis, mentors présents tout le week-end. Pitch final devant un jury le dimanche après-midi.', '2026-10-24T09:00:00+02:00', '2026-10-25T18:00:00+01:00', 'scheduled', 'hybrid', 'Toulouse', 'Toulouse Montaudran', 'ai', array['Hackathon', 'Open data', 'Mobilité'], array['Python', 'GTFS'], array['Étudiants', 'Développeurs', 'Data scientists'], 'Tous niveaux', true, 0, 0, 'French Tech Toulouse', 'https://example.com/hackathon-ia-mobilite'),
  ('journee-recrutement-data-ia-paris', 'Journée recrutement Data et IA', 'Une trentaine d''entreprises recrutent des profils data, du stage au poste senior. Entretiens sur place.', 'Pense à apporter plusieurs CV. Des ateliers de relecture de CV ont lieu toutes les heures.', '2026-10-29T10:00:00+01:00', '2026-10-29T17:00:00+01:00', 'scheduled', 'in_person', 'Paris', 'Paris 15e', 'data', array['Recrutement', 'Carrière'], '{}'::text[], array['Étudiants', 'Juniors', 'Data engineers'], 'Débutant', true, 0, 0, 'Data Jobs France', 'https://example.com/journee-recrutement-data-ia'),
